func (st ServerType) parsePortOption(d *caddyfile.Dispenser, _ interface{}) (interface{}, error) {
	st.optionState.lastName = d.Val()
	if st.optionState.current == nil {
		st.optionState.current = make(map[string]interface{})
	}
	var port int
	for d.Next() {
		var portStr string
		if !d.AllArgs(&portStr) {
			return 0, d.ArgErr()
		}
		var err error
		port, err = strconv.Atoi(portStr)
		if err != nil {
			return 0, d.Errf("converting port '%s' to integer value: %v", portStr, err)
		}
	}
	st.optionState.current[st.optionState.lastName] = port
	return port, nil
}

func parseOptOrder(d *caddyfile.Dispenser, _ interface{}) (interface{}, error) {
	newOrder := directiveOrder

	for d.Next() {
		// get directive name
		if !d.Next() {
			return nil, d.ArgErr()
		}
		dirName := d.Val()
		if _, ok := registeredDirectives[dirName]; !ok {
			return nil, d.Errf("%s is not a registered directive", dirName)
		}

		// get positional token
		if !d.Next() {
			return nil, d.ArgErr()
		}
		pos := d.Val()

		// if directive exists, first remove it
		for i, d := range newOrder {
			if d == dirName {
				newOrder = append(newOrder[:i], newOrder[i+1:]...)
				break
			}
		}

		// act on the positional
		switch pos {
		case "first":
			newOrder = append([]string{dirName}, newOrder...)
			if d.NextArg() {
				return nil, d.ArgErr()
			}
			directiveOrder = newOrder
			return newOrder, nil
		case "last":
			newOrder = append(newOrder, dirName)
			if d.NextArg() {
				return nil, d.ArgErr()
			}
			directiveOrder = newOrder
			return newOrder, nil
		case "before":
		case "after":
		default:
			return nil, d.Errf("unknown positional '%s'", pos)
		}

		// get name of other directive
		if !d.NextArg() {
			return nil, d.ArgErr()
		}
		otherDir := d.Val()
		if d.NextArg() {
			return nil, d.ArgErr()
		}

		// insert directive into proper position
		for i, d := range newOrder {
			if d == otherDir {
				if pos == "before" {
					newOrder = append(newOrder[:i], append([]string{dirName}, newOrder[i:]...)...)
				} else if pos == "after" {
					newOrder = append(newOrder[:i+1], append([]string{dirName}, newOrder[i+1:]...)...)
				}
				break
			}
		}
	}

	directiveOrder = newOrder

	return newOrder, nil
}

func parseOptStorage(d *caddyfile.Dispenser, _ interface{}) (interface{}, error) {
	if !d.Next() { // consume option name
		return nil, d.ArgErr()
